  const it=rfq.items[0],q0=it.qty,sup=uname(q.supplier),bo=orgName(rfq.buyer),mk=(type,at,actor,org,qty,mode,evid,exc)=>o.events.push({type,at,actor,org,qty:qty||0,unit:it.unit,mode:mode||"",evid:evid||"",exc:exc||""});
