  $("#modalBox").querySelector("[data-cancel]").onclick=closeModal;
  $("#fOk").onclick=()=>{const v={};for(const x of o.fields||[]){v[x.id]=$("#f_"+x.id).value.trim();if(x.req&&!v[x.id]){toast(x.label+" is required","bad");$("#f_"+x.id).focus();return}if(x.min&&v[x.id].length<x.min){toast(x.label+" needs at least "+x.min+" characters","bad");return}}
    if(o.onSubmit(v)!==false)closeModal()};
  const first=$("#modalBox").querySelector("select,textarea,input");if(first)first.focus();
