const REASON={id:"reason",label:"Reason (recorded in the audit log)",type:"textarea",req:true,min:8,ph:"At least 8 characters"};
function guard(perm,on){if(can(perm))return true;refuse(perm,on);return false}
function done(msg){toast(msg,"ok");refreshCounts();redraw()}

function mount(id,el,m){
  const cfg=REG[id](),st=MS[id]||(MS[id]={q:"",f:"all",page:0});CFGS[id]=cfg;
  if(cfg.custom){el.innerHTML=head(m)+cfg.custom(st);if(cfg.after)cfg.after(el,st);return}
  el.innerHTML=head(m)+(cfg.banner?`<div class="mbanner">${cfg.banner}</div>`:"")+`<div class="eyebrow">Key figures</div><div class="kpis" id="m-kpis"></div><div class="eyebrow">${esc(cfg.dirTitle||"Directory")}</div><div class="toolbar" id="m-tool"></div><div class="tablewrap"><div class="tscroll"><table><thead id="m-head"></thead><tbody id="m-body"></tbody></table></div><div class="foot" id="m-foot"></div></div>`;
  drawAll(id);
}
function rowsOf(id){const cfg=CFGS[id],st=MS[id];let r=cfg.rows();if(st.f!=="all")r=r.filter(x=>cfg.filter?cfg.filter(x,st.f):cfg.status(x)===st.f);if(st.q){const q=st.q.toLowerCase();r=r.filter(x=>cfg.search(x).toLowerCase().includes(q))}return cfg.sort?r.slice().sort(cfg.sort):r}
function drawAll(id){
  const cfg=CFGS[id],st=MS[id];if(!cfg||!$("#m-kpis"))return;
  $("#m-kpis").innerHTML=cfg.kpis().map(([l,v,s,c,f])=>`<div class="kpi${c?" "+c:""}${f?" clk":""}" ${f?`data-mkpi="${esc(f)}" role="button" tabindex="0"`:""}><div class="lab">${esc(l)}</div><div class="val tnum">${v}</div><div class="sub">${s||"&nbsp;"}</div></div>`).join("");
  TOOLS=cfg.tools||[];
  const exp=cfg.export;
  $("#m-tool").innerHTML=`<input type="search" id="mq" placeholder="${esc(cfg.ph||"Search…")}" value="${esc(st.q)}" aria-label="Search directory">${cfg.filters?`<div class="seg" id="mseg">${cfg.filters.map(([v,l])=>`<button data-mf="${esc(v)}" aria-pressed="${st.f===v}">${esc(l)}</button>`).join("")}</div>`:""}${TOOLS.map((t,i)=>`<button class="btn ${t[1]||""}" data-mtool="${i}" ${t[2]?lock(t[2]):""}>${t[0]}</button>`).join("")}${exp?`<button class="btn" data-mexport="${id}" style="margin-left:auto" ${lock(exp.perm)}>Export CSV</button>`:""}`;
  $("#m-head").innerHTML=`<tr>${cfg.cols.map(c=>`<th>${esc(c[0])}</th>`).join("")}</tr>`;
  drawTable(id);
}
function drawTable(id){
  const cfg=CFGS[id],st=MS[id],rows=rowsOf(id),pages=Math.max(1,Math.ceil(rows.length/PAGE));if(st.page>=pages)st.page=pages-1;
  const slice=rows.slice(st.page*PAGE,st.page*PAGE+PAGE);
  $("#m-body").innerHTML=slice.length?slice.map(r=>`<tr data-mrow="${esc(cfg.rid(r))}" tabindex="0">${cfg.cols.map(c=>`<td>${c[1](r)}</td>`).join("")}</tr>`).join(""):`<tr><td colspan="${cfg.cols.length}"><div class="empty">${cfg.empty||"Nothing matches these filters."}</div></td></tr>`;
  $("#m-foot").innerHTML=`<span>Showing ${rows.length?st.page*PAGE+1:0}–${st.page*PAGE+slice.length} of ${rows.length}</span><span class="sp"></span><button class="btn sm" data-mpage="-1" ${st.page?"":"disabled"}>Prev</button><span>${st.page+1}/${pages}</span><button class="btn sm" data-mpage="1" ${st.page+1<pages?"":"disabled"}>Next</button><span class="ft">Demo paginates in the browser; production must paginate server-side.</span>`;
}
function openDetail(id,rowId){
  const cfg=CFGS[id]||(REG[id]&&(CFGS[id]=REG[id]()));if(!cfg||!cfg.detail)return;
  const row=cfg.rows().find(r=>cfg.rid(r)===rowId);if(!row)return;
  const d=cfg.detail(row);CUR={id,rowId};ACTS=d.actions||[];
  $("#drawer").innerHTML=`<div class="drawer-h"><div><div class="hid">${d.kicker||""}</div><h2>${d.title}</h2></div><button class="closex" data-close aria-label="Close">✕</button></div><div class="drawer-b">${d.body}</div><div class="drawer-f">${ACTS.map((a,i)=>`<button class="btn ${a.cls||""}" data-mact="${i}" ${a.perm?lock(a.perm):""}>${a.label}</button>`).join("")||'<span class="meta">No actions for this record.</span>'}</div>`;
  showDrawer();
}
function redraw(){const open=$("#drawer").classList.contains("on");if(CUR&&CFGS[CUR.id]&&currentView===CUR.id){drawAll(CUR.id);if(open)openDetail(CUR.id,CUR.rowId)}else if(currentView in REG&&CFGS[currentView])show(currentView)}
function jump(view,rid){if(!MODULES[view]||!can(MODULES[view].perm)){refuse(MODULES[view]?MODULES[view].perm:view,view+" "+rid);return}closeDrawer();show(view);if(rid)setTimeout(()=>openDetail(view,rid),0)}

document.addEventListener("click",e=>{
  const t=e.target;
  const gv=t.closest("[data-gv]");if(gv){e.preventDefault();jump(gv.dataset.gv,gv.dataset.gid);return}
  const act=t.closest("[data-mact]");if(act&&!act.disabled){const a=ACTS[+act.dataset.mact];if(!a)return;if(a.perm&&!guard(a.perm,(CUR?CUR.rowId:"")))return;a.fn();return}
  const tool=t.closest("[data-mtool]");if(tool&&!tool.disabled){const a=TOOLS[+tool.dataset.mtool];if(a)a[3]();return}
  const f=t.closest("[data-mf]");if(f&&MS[currentView]){MS[currentView].f=f.dataset.mf;MS[currentView].page=0;drawAll(currentView);return}
  const k=t.closest("[data-mkpi]");if(k&&MS[currentView]){const s=MS[currentView];s.f=s.f===k.dataset.mkpi?"all":k.dataset.mkpi;s.page=0;drawAll(currentView);return}
  const pg=t.closest("[data-mpage]");if(pg&&!pg.disabled&&MS[currentView]){MS[currentView].page+=+pg.dataset.mpage;drawTable(currentView);return}
  const ex=t.closest("[data-mexport]");if(ex&&!ex.disabled){const id=ex.dataset.mexport,c=CFGS[id].export;if(!guard(c.perm,id))return;let rows=rowsOf(id);if(c.filter)rows=rows.filter(c.filter);csv(c.name,c.header,rows.map(c.row));audit(id+".export",`Exported ${rows.length} ${MODULES[id].label} rows`,"warn","");toast("Exported "+rows.length+" rows","ok");return}
  const row=t.closest("tr[data-mrow]");if(row&&!t.closest("button,a,input")){openDetail(currentView,row.dataset.mrow);return}
});
document.addEventListener("keydown",e=>{if(e.key!=="Enter")return;const row=e.target.closest&&e.target.closest("tr[data-mrow]");if(row)openDetail(currentView,row.dataset.mrow);const k=e.target.closest&&e.target.closest("[data-mkpi]");if(k)k.click()});
